/* ═══════════════════════════════════════════════════════════════════
   SUNKUU 360 — Centro de Exportación · v3
   Tokens: --navy #00008C · --teal #00EBC8 · --bg #EBF0F7 · --brd #D4E0EE
   v3: variables :root, hardcoded→tokens, legibilidad mejorada,
       emojis→Material Icons
   ═══════════════════════════════════════════════════════════════════ */

#exp-root {
  --navy: #00008C;
  --teal: #00EBC8;
  --bg:   #EBF0F7;
  --surf: #FFFFFF;
  --pri:  #0D1B2E;
  --sec:  #5A6E8A;
  --ter:  #96AABF;
  --brd:  #D4E0EE;
  --pos:  #10B981;
  --neg:  #EF4444;
  --warn: #F59E0B;
  --ind:  #6366F1;
  --shd:  0 1px 3px rgba(13,27,46,.06), 0 8px 28px rgba(13,27,46,.08);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

#exp-root {
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  background: var(--bg);
  height: auto;
  overflow-x: hidden;
  display: flex;
  flex-direction: column;
}

/* ── HEADER ────────────────────────────────────────────────────────── */
#exp-header {
  background: var(--navy);
  padding: 16px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  box-shadow: 0 2px 14px rgba(0,0,0,.32);
}

#exp-header-left {
  display: flex;
  align-items: center;
  gap: 14px;
}

#exp-logo {
  display: flex;
  align-items: center;
  gap: 8px;
}
.brand-img{height:22px;width:auto;display:block}

.logo-sub  { font-weight: 400; font-size: 9px; color: rgba(255,255,255,.8); margin-left: 4px; letter-spacing: .05em; }

#exp-title {
  font-size: 17px;
  font-weight: 800;
  color: white;
  letter-spacing: -.02em;
  line-height: 1.1;
}

#exp-subtitle {
  font-size: 11px;
  color: rgba(255,255,255,.6);
  margin-top: 3px;
}

/* ── BODY ──────────────────────────────────────────────────────────── */
#exp-body {
  display: grid;
  grid-template-columns: 3fr 2fr;
  gap: 18px;
  padding: 20px 24px 32px;
  align-items: start;
  flex: 1;
}

/* ── SECCIONES ─────────────────────────────────────────────────────── */
.exp-section {
  background: var(--surf);
  border-radius: 16px;
  border: 1px solid var(--brd);
  box-shadow: var(--shd);
  padding: 18px 20px;
  margin-bottom: 14px;
}
.exp-section:last-child { margin-bottom: 0; }

.section-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.sec-num {
  width: 28px; height: 28px;
  border-radius: 7px;
  background: linear-gradient(135deg, var(--navy), #0a0abb);
  display: flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 800; color: var(--teal);
  flex-shrink: 0;
  box-shadow: 0 2px 8px rgba(0,0,140,.25);
}
.sec-num-sm { font-size: 14px; }

.sec-title {
  font-size: 15px;
  font-weight: 800;
  color: var(--navy);
  letter-spacing: -.01em;
}

/* ── INSTALACIÓN: TARJETAS ─────────────────────────────────────────── */
#inst-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.inst-card {
  border: 2px solid var(--brd);
  border-radius: 12px;
  padding: 12px 13px;
  cursor: pointer;
  background: var(--surf);
  text-align: left;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  transition: all .15s;
  width: 100%;
}
.inst-card:hover:not(.offline) {
  border-color: var(--teal);
  background: rgba(0,235,200,.04);
}
.inst-card.active {
  border-color: var(--teal);
  background: rgba(0,235,200,.06);
  box-shadow: 0 0 0 3px rgba(0,235,200,.18);
}
.inst-card.offline {
  opacity: .55;
  cursor: not-allowed;
}

.inst-dot {
  width: 7px; height: 7px;
  border-radius: 50%;
  margin-top: 3px; flex-shrink: 0;
}
.inst-dot.online  { background: var(--pos); box-shadow: 0 0 4px rgba(16,185,129,.7); }
.inst-dot.offline { background: var(--neg); }

.inst-info  { flex: 1; min-width: 0; }
.inst-name  { font-size: 12px; font-weight: 700; color: var(--pri); line-height: 1.2; }
.inst-client{ font-size: 10px; color: var(--sec); margin-top: 2px; }

.inst-badge {
  display: inline-block;
  margin-top: 5px;
  padding: 2px 7px;
  border-radius: 20px;
  font-size: 9px; font-weight: 700;
}
.inst-badge.em      { background: rgba(0,0,140,.08); color: var(--navy); }
.inst-badge.piscina { background: #EEF2FF; color: var(--ind); }

/* ── B-05: filtro por customer (E3), estado vacío y aviso de límite ── */
#client-chips { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 10px; }
.client-chip {
  padding: 4px 11px;
  border-radius: 20px;
  border: 1px solid var(--brd);
  background: var(--surf);
  cursor: pointer;
  font-size: 11px; font-weight: 600;
  font-family: inherit;
  color: var(--sec);
}
.client-chip:hover  { border-color: var(--navy); color: var(--navy); }
.client-chip.active { border-color: var(--navy); background: var(--navy); color: white; }
.inst-empty {
  grid-column: 1 / -1;
  font-size: 12px; color: var(--ter);
  font-style: italic; padding: 10px 0;
}
.exp-result.warn {
  background: rgba(245,158,11,.08);
  border: 1px solid rgba(245,158,11,.3);
  color: #92400E;
}

/* ── VARIABLES: GRUPOS Y PILLS ─────────────────────────────────────── */
#var-controls {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-left: auto;
  flex-wrap: wrap;
}

.ctrl-btn {
  padding: 4px 12px;
  border-radius: 7px;
  border: 1px solid var(--brd);
  background: transparent;
  cursor: pointer;
  font-size: 11px; font-weight: 600;
  color: var(--navy);
}
.ctrl-btn:hover { background: rgba(0,0,140,.06); }

.var-counter {
  font-size: 11px; font-weight: 700;
  color: var(--navy);
  background: rgba(0,235,200,.12);
  border: 1px solid rgba(0,235,200,.28);
  padding: 4px 10px;
  border-radius: 7px;
}

.var-group       { margin-bottom: 12px; }
.var-group:last-child { margin-bottom: 0; }

.var-group-title {
  font-size: 10px; font-weight: 700;
  letter-spacing: .07em; text-transform: uppercase;
  color: var(--sec);
  margin-bottom: 7px;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--brd);
}

.var-pills { display: flex; flex-wrap: wrap; gap: 6px; }

.var-pill {
  display: flex; align-items: center; gap: 5px;
  padding: 5px 11px;
  border-radius: 20px;
  border: 1px solid var(--brd);
  background: transparent;
  cursor: pointer;
  font-size: 11px; font-weight: 500;
  color: var(--sec);
  transition: all .12s;
  user-select: none;
}
.var-pill input { display: none; }
.var-pill:hover { border-color: var(--teal); color: var(--navy); }

.var-pill.checked {
  border-color: var(--teal);
  background: rgba(0,235,200,.1);
  color: var(--navy);
  font-weight: 600;
}

.pill-check { font-size: 10px; color: var(--teal); display: none; }
.var-pill.checked .pill-check { display: inline; }

/* ── PERÍODO ───────────────────────────────────────────────────────── */
#period-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.field-label {
  font-size: 12px; font-weight: 600;
  color: var(--sec);
  margin-bottom: 7px;
}

#date-row {
  display: flex; align-items: center; gap: 8px;
  margin-bottom: 10px;
}

.date-field { flex: 1; }
.date-label { font-size: 10px; color: var(--sec); margin-bottom: 4px; }

.date-input {
  width: 100%;
  background: #F0F6FC;
  border: 1px solid var(--brd);
  border-radius: 8px;
  padding: 7px 10px;
  font-size: 11px; color: var(--pri); font-weight: 600;
  cursor: pointer;
}
.date-input:focus { outline: none; border-color: var(--teal); }

.date-sep { font-size: 12px; color: var(--sec); flex-shrink: 0; }

#quick-btns { display: flex; gap: 6px; flex-wrap: wrap; }
.quick-btn {
  padding: 5px 11px;
  border-radius: 7px;
  border: 1px solid var(--brd);
  background: transparent;
  cursor: pointer;
  font-size: 11px; font-weight: 600;
  color: var(--sec);
  transition: all .12s;
}
.quick-btn:hover { border-color: var(--navy); background: rgba(0,0,140,.06); color: var(--navy); }
.quick-btn.active { border-color: var(--navy); background: var(--navy); color: white; }

.gran-select {
  width: 100%;
  background: #F0F6FC;
  border: 1px solid var(--brd);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 11px; color: var(--pri); font-weight: 600;
  cursor: pointer;
}
.gran-select:focus { outline: none; border-color: var(--teal); }

.agg-wrap { transition: opacity .2s; }
.agg-wrap.disabled { opacity: .4; pointer-events: none; }

.raw-warning {
  font-size: 11px;
  color: var(--warn);
  background: rgba(245,158,11,.08);
  border: 1px solid rgba(245,158,11,.22);
  border-radius: 7px;
  padding: 6px 10px;
  margin-top: 8px;
}

.tip-box {
  margin-top: 10px;
  padding: 8px 11px;
  background: rgba(0,235,200,.06);
  border: 1px solid rgba(0,235,200,.18);
  border-radius: 8px;
  font-size: 10px; color: var(--sec);
  line-height: 1.5;
  display: flex; align-items: flex-start; gap: 6px;
}
.tip-ico {
  font-family: 'Material Icons';
  font-size: 16px; color: var(--teal);
  font-style: normal; font-weight: normal;
  line-height: 1.4; user-select: none; flex-shrink: 0;
}

/* ── RESUMEN ───────────────────────────────────────────────────────── */
.summ-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 8px 0;
  border-bottom: 1px solid var(--brd);
  gap: 8px;
}
.summ-row:last-child { border-bottom: none; }

.summ-label { font-size: 12px; color: var(--sec); flex-shrink: 0; }
.summ-val   { font-size: 12px; font-weight: 600; color: var(--pri); text-align: right; font-variant-numeric: tabular-nums; }

/* ── BOTÓN EXPORTAR ────────────────────────────────────────────────── */
#btn-export {
  width: 100%;
  background: var(--teal);
  border: none;
  border-radius: 14px;
  padding: 15px 24px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  box-shadow: 0 4px 16px rgba(0,235,200,.4);
  transition: all .2s;
  margin-bottom: 12px;
}
#btn-export:hover:not(:disabled) {
  background: #00d4b4;
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(0,235,200,.5);
}
#btn-export:disabled {
  background: #CBD5E1;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}
#btn-icon {
  font-family: 'Material Icons';
  font-size: 20px; font-style: normal; font-weight: normal;
  line-height: 1; user-select: none;
  color: var(--navy);
}
#btn-text { font-size: 14px; font-weight: 700; color: var(--navy); }

/* ── PROGRESO ──────────────────────────────────────────────────────── */
#exp-progress { flex-direction: column; gap: 6px; margin-bottom: 10px; }

#progress-bar-track {
  width: 100%; height: 6px;
  background: var(--brd);
  border-radius: 3px; overflow: hidden;
}
#progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--navy), var(--teal));
  border-radius: 3px;
  width: 0%;
  transition: width .3s ease;
}
#progress-label { font-size: 11px; color: var(--sec); font-weight: 500; }

/* ── RESULTADO ─────────────────────────────────────────────────────── */
.exp-result {
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 12px; font-weight: 600;
  line-height: 1.4;
}
.exp-result.success {
  background: #ECFDF5;
  border: 1px solid rgba(16,185,129,.3);
  color: #065F46;
}
.exp-result.error {
  background: #FEF2F2;
  border: 1px solid rgba(239,68,68,.3);
  color: #991B1B;
}

/* ── HISTORIAL ─────────────────────────────────────────────────────── */
.hist-note { font-size: 10px; color: var(--ter); margin-left: auto; font-style: italic; }

.hist-empty {
  font-size: 12px; color: var(--ter);
  text-align: center; padding: 14px 0; font-style: italic;
}

.hist-item {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 0;
  border-top: 1px solid var(--brd);
}
.hist-info  { flex: 1; min-width: 0; }
.hist-label { font-size: 12px; font-weight: 600; color: var(--pri); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hist-meta  { font-size: 11px; color: var(--sec); margin-top: 2px; }
.hist-fecha { font-size: 10px; color: var(--ter); }

.hist-btn {
  font-size: 11px; font-weight: 700;
  color: var(--navy);
  background: rgba(0,0,140,.07);
  border: 1px solid rgba(0,0,140,.15);
  border-radius: 6px;
  padding: 4px 9px;
  cursor: pointer; flex-shrink: 0;
}
.hist-btn:hover { background: rgba(0,0,140,.13); }

/* ── BOTÓN VOLVER ──────────────────────────────────────────────────── */
#btn-back {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 8px;
  padding: 6px 12px;
  cursor: pointer;
  color: rgba(255,255,255,.8);
  font-size: 12px; font-weight: 700;
  font-family: inherit;
  transition: all .15s;
  flex-shrink: 0; white-space: nowrap;
  display: flex; align-items: center; gap: 6px;
}
#btn-back:hover { background: rgba(255,255,255,.16); color: white; }

#exp-header-right { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }

/* ── RESPONSIVE ────────────────────────────────────────────────────── */
@media (max-width: 900px) {
  #exp-body    { grid-template-columns: 1fr; padding: 14px 16px 24px; }
  #inst-grid   { grid-template-columns: repeat(2, 1fr); }
  #period-grid { grid-template-columns: 1fr; }
}

@media (max-width: 700px) {
  #exp-header                       { padding: 10px 14px; }
  #exp-header-left                  { gap: 10px; }
  #exp-subtitle                     { display: none; }
  #exp-header-left > div:last-child { min-width: 0; overflow: hidden; }
  #exp-title     { font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 160px; }
  #exp-logo      { gap: 6px; }
  #exp-logo .brand-img{height:18px}
}

@media (max-width: 480px) {
  #exp-header-left > div:last-child { display: none; }
}

@media (max-width: 600px) {
  #exp-body   { padding: 10px 12px 20px; }
  #inst-grid  { grid-template-columns: 1fr; }
  #exp-right  { order: -1; }
  #quick-btns { flex-direction: column; }
  .quick-btn  { width: 100%; text-align: center; padding: 8px 11px; }
}

controllerScript.body:
/**
 * CENTRO DE EXPORTACIÓN v2 — Controller Script
 * ThingsBoard PE 4.3.0PE · Sunkuu 360
 *
 * CAMBIOS respecto a v1:
 *   - DEVICES → INSTALLATIONS: instalaciones con múltiples dispositivos agrupados
 *   - Piscina Temperada: exporta de 3 dispositivos simultáneamente en un solo CSV
 *   - Variables agrupadas por categoría con etiquetas amigables
 *   - Keys actualizados a nombres reales confirmados en TB
 *   - Todas las funciones auxiliares (buildCSV, downloadCSV, fetchRaw, etc.) SIN cambios
 *
 * B-05 (copia DEV): instalaciones desde el registro (sunkuu-registro.js, alias registroMod), filtro por
 *   customer (E3), catálogo (contador de energía), Raw paginado por variable (tope de 10 × 50 000 con aviso),
 *   CSV con la etiqueta de la instalación y sin el estado fijo status:'online' (F51).
 *
 * IDs de elementos HTML requeridos (deben existir en el template HTML):
 *   #inst-grid     → tarjetas de selección de instalación
 *   #var-groups    → contenedor de grupos de variables
 *   .var-chk       → checkboxes de variables (clase, no ID)
 *   #btn-all       → botón "Todas"
 *   #btn-none      → botón "Ninguna"
 *   #var-counter   → contador "X de Y seleccionadas"
 *   #dt-from       → input fecha desde
 *   #dt-to         → input fecha hasta
 *   .quick-btn     → botones de período rápido (con data-days)
 *   #sel-gran      → selector de granularidad
 *   #agg-wrap      → contenedor de agregación (clase disabled cuando raw)
 *   #raw-warning   → aviso de raw
 *   #sel-agg       → selector de agregación
 *   #summary-inst  → resumen: nombre instalación
 *   #summary-vars  → resumen: variables seleccionadas
 *   #summary-period→ resumen: período
 *   #summary-gran  → resumen: granularidad
 *   #summary-rows  → resumen: filas estimadas
 *   #btn-export    → botón exportar
 *   #btn-text      → texto del botón
 *   #btn-icon      → icono del botón
 *   #exp-progress  → contenedor de progreso
 *   #progress-fill → barra de progreso (width en %)
 *   #progress-label→ texto de progreso
 *   #exp-result    → mensaje de resultado
 *   #hist-list     → lista de historial
 */
self.onInit = function() {
  var ctx = self.ctx;
  self.ctx.$container.css({'overflow-y':'auto','height':'100%'});

  /* ── INSTALACIONES DESDE EL REGISTRO (B-05) ──────────────────────── */
  /* Salen de sunkuu-registro.js (B-02), declarado en el editor JavaScript con alias registroMod.
   * ThingsBoard filtra por permisos: un usuario de customer solo recibe sus instalaciones.
   * Sin registro o con error → lista vacía y mensaje (fail-closed).
   * Cada instalación: { id, label, client, type, badge, dashboardId, devices:[{id,name}], varGroups }.
   * Cada variable lleva `di` (índice en `devices`), como antes. */
  var REG = (typeof registroMod !== 'undefined' && registroMod && registroMod.loadInstallations) ? registroMod : window.SunkuuRegistro;
  var LIMIT_PUNTOS = 50000;    /* Raw: puntos por página (una variable por consulta) */
  var MAX_PAGINAS  = 10;       /* Raw: tope de seguridad por variable (500 000 puntos); solo entonces se avisa */

  /* ── ESTADO INTERNO ───────────────────────────────────────────────── */
  var VISIBLE_INSTALLATIONS = [];
  var selInstIdx = -1;         /* índice en VISIBLE_INSTALLATIONS; -1 = ninguna */
  var selClient = null;        /* filtro E3: propietario elegido; null = todos */
  var exportHistory = [];      /* historial en memoria de sesión */

  var stateParams = self.ctx.stateController.getStateParams();

  function cargarInstalaciones() {
    document.getElementById('btn-export').disabled = true;
    if (!REG) { mostrarVacio('No se pudo cargar el registro de instalaciones'); return; }
    document.getElementById('inst-grid').innerHTML = '<div class="inst-empty">Cargando instalaciones…</div>';
    REG.loadInstallations(ctx, function (res) {
      VISIBLE_INSTALLATIONS = res.instalaciones.map(function (i) {
        var ex = REG.exportacion(i);
        return { id: i.id, label: i.etiqueta, client: i.owner, type: i.tipo, badge: REG.CATALOGO[i.tipo].nombre,
                 dashboardId: i.dashboardId,
                 devices: ex.devices.map(function (d) { return { id: d.id, name: d.nombre }; }),
                 varGroups: ex.varGroups };
      });
      if (!VISIBLE_INSTALLATIONS.length) {
        mostrarVacio(res.mensaje + (res.ok ? '' : ' (no se pudo leer el registro)'));
        return;
      }
      /* Pre-selección: ?from= (dashboard de origen) o el parámetro de estado instId (UUID del activo) */
      var fromDash = new URLSearchParams(window.location.search).get('from') || '';
      var pre      = REG.porDashboard(res.instalaciones, fromDash);
      var instId   = pre ? pre.id : (stateParams && stateParams.instId) || null;
      selInstIdx = 0;
      VISIBLE_INSTALLATIONS.forEach(function (inst, i) { if (inst.id === instId) selInstIdx = i; });
      document.getElementById('btn-export').disabled = false;
      renderClientChips();
      renderInstCards();
      renderVarGroups();
      updateSummary();
    });
  }

  function mostrarVacio(msg) {
    VISIBLE_INSTALLATIONS = [];
    selInstIdx = -1;
    var cc = document.getElementById('client-chips');
    if (cc) cc.style.display = 'none';
    document.getElementById('inst-grid').innerHTML = '<div class="inst-empty">' + esc(msg) + '</div>';
    document.getElementById('var-groups').innerHTML = '';
    document.getElementById('btn-export').disabled = true;
    updateVarCounter();
    updateSummary();
  }

  /* ── FILTRO POR CUSTOMER (E3) ────────────────────────────────────── */
  /* Un chip por propietario. Solo con más de un propietario (admin del tenant). */
  function renderClientChips() {
    var box = document.getElementById('client-chips');
    if (!box) return;
    var owners = [];
    VISIBLE_INSTALLATIONS.forEach(function (inst) { if (owners.indexOf(inst.client) < 0) owners.push(inst.client); });
    owners.sort(function (a, b) { return String(a).localeCompare(String(b), 'es'); });
    box.innerHTML = '';
    if (owners.length < 2) { selClient = null; box.style.display = 'none'; return; }
    box.style.display = '';
    [null].concat(owners).forEach(function (o) {
      var chip = document.createElement('button');
      chip.className = 'client-chip' + (o === selClient ? ' active' : '');
      chip.textContent = o === null ? 'Todos los customers' : o;
      chip.addEventListener('click', function () {
        selClient = o;
        var cur = VISIBLE_INSTALLATIONS[selInstIdx];
        if (o !== null && (!cur || cur.client !== o)) {
          VISIBLE_INSTALLATIONS.some(function (inst, i) { if (inst.client === o) { selInstIdx = i; return true; } return false; });
        }
        renderClientChips();
        renderInstCards();
        renderVarGroups();
        updateSummary();
      });
