  /* ── EXPORT PRINCIPAL ─────────────────────────────────────────────── */
  function startExport() {
    var inst = VISIBLE_INSTALLATIONS[selInstIdx];
    if (!inst) {
      showResult('⚠ No hay ninguna instalación seleccionada.', 'error');
      return;
    }
    var selectedVars = [];
    document.querySelectorAll('.var-chk:checked').forEach(function(c) {
      selectedVars.push({ k: c.value, di: parseInt(c.getAttribute('data-di')), l: c.getAttribute('data-label') });
    });

    if (selectedVars.length === 0) {
      showResult('⚠ Selecciona al menos una variable.', 'error');
      return;
    }

    var startTs = new Date(document.getElementById('dt-from').value).getTime();
    var endTs   = new Date(document.getElementById('dt-to').value).getTime();

    if (isNaN(startTs) || isNaN(endTs) || startTs >= endTs) {
      showResult('⚠ Rango de fechas inválido.', 'error');
      return;
    }

    var gran = document.getElementById('sel-gran').value;
    var agg  = document.getElementById('sel-agg').value;

    setLoading(true);
    showProgress(0, 'Conectando con el servidor...');

    /* Agrupar vars seleccionadas por dispositivo */
    var byDevice = {};
    selectedVars.forEach(function(v) {
      if (!byDevice[v.di]) byDevice[v.di] = [];
      byDevice[v.di].push(v);
    });

    var deviceIndices = Object.keys(byDevice).map(Number);

    /* Para instalaciones de un solo dispositivo (3EM) */
    if (deviceIndices.length === 1 && inst.devices.length === 1) {
      var keys = byDevice[0].map(function(v) { return v.k; });
      if (gran === 'raw') {
        fetchRaw(inst.label, inst.devices[0], byDevice[0], startTs, endTs);
      } else {
        fetchAggregated(inst.label, inst.devices[0], keys, startTs, endTs, gran, agg);
      }
      return;
    }

    /* Para instalaciones multi-dispositivo (Piscina): fetch paralelo + merge */
    fetchMultiDevice(inst, byDevice, selectedVars, startTs, endTs, gran, agg);
  }

  /* ── FETCH MULTI-DISPOSITIVO (Piscina) ───────────────────────────── */
  function fetchMultiDevice(inst, byDevice, allVars, startTs, endTs, gran, agg) {
    var deviceIndices = Object.keys(byDevice).map(Number);
    var results = {};
    var failed = false;
    var totalKeys = allVars.length;
    var completedKeys = 0;
    var cortadas = [];

    function fetchNextDevice(diIdx) {
      if(diIdx >= deviceIndices.length) {
        showProgress(90, 'Generando CSV...');
        var mergedData = mergeMultiDeviceData(results, byDevice, allVars);
        var csv = buildCSVFromMerged(mergedData, allVars);
        var filename = buildFilename(inst.label, startTs, endTs, gran === 'raw' ? 'raw' : gran);
        downloadCSV(csv, filename);
        showProgress(100, 'Listo.'); setLoading(false);
        var rowCount = Object.keys(mergedData).length;
        showFin(filename, rowCount, cortadas);
        addToHistory(inst.label, startTs, endTs, gran, allVars.length, rowCount);
        return;
      }
      var di = deviceIndices[diIdx];
      var device = inst.devices[di];
      var keys = byDevice[di].map(function(v){ return v.k; });
      var devData = {};
      var keyIdx = 0;

      function fetchNextKey() {
        if(keyIdx >= keys.length) {
          results[di] = devData;
          fetchNextDevice(diIdx + 1);
          return;
        }
        var key = keys[keyIdx];
        completedKeys++;
        showProgress(5 + Math.round((completedKeys / totalKeys) * 80),
          device.name + ' · ' + key + ' (' + completedKeys + '/' + totalKeys + ')');

        if(gran === 'raw') {
          fetchKeyRaw(device, byDevice[di][keyIdx], startTs, endTs, cortadas, function(pts) {
            if(failed) return;
            if(pts.length) devData[key] = pts;
            keyIdx++; fetchNextKey();
          }, function() {
            if(failed) return; failed = true; setLoading(false);
            showResult('❌ Error al obtener ' + key + ' de ' + device.name + '.', 'error');
          });
        } else {
          var MAX_MS = 4999 * parseInt(gran);
          var chunks = [], cs = startTs;
          while(cs < endTs){ var ce = Math.min(cs+MAX_MS,endTs); chunks.push({s:cs,e:ce}); cs=ce; }
          var keyData = [], chunkIdx = 0;
          function fetchNextChunk() {
            if(chunkIdx >= chunks.length) {
              devData[key] = keyData;
              keyIdx++; fetchNextKey();
              return;
            }
            var chunk = chunks[chunkIdx];
            var url = '/api/plugins/telemetry/DEVICE/' + device.id +
                      '/values/timeseries?keys=' + key +
                      '&startTs=' + chunk.s + '&endTs=' + chunk.e +
                      '&interval=' + gran + '&agg=' + agg + '&limit=50000';
            ctx.http.get(url).subscribe(function(data) {
              if(failed) return;
              if(data[key]) keyData = keyData.concat(data[key]);
              chunkIdx++; fetchNextChunk();
            }, function() {
              if(failed) return; failed = true; setLoading(false);
              showResult('❌ Error al obtener ' + key + ' de ' + device.name + '.', 'error');
            });
          }
          fetchNextChunk();
        }
      }
      fetchNextKey();
    }
    fetchNextDevice(0);
  }

  /* Unificar datos de múltiples dispositivos por timestamp */
  function mergeMultiDeviceData(results, byDevice, allVars) {
    var tsMap = {};
    Object.keys(results).forEach(function(di) {
      var data = results[di];
      byDevice[di].forEach(function(v) {
        if (data[v.k]) {
          data[v.k].forEach(function(point) {
            if (!tsMap[point.ts]) tsMap[point.ts] = {};
            tsMap[point.ts][v.k] = point.value;
          });
        }
      });
    });
    return tsMap;
  }

  /* Construir CSV desde tsMap con todas las variables */
  function buildCSVFromMerged(tsMap, allVars) {
    var keys     = allVars.map(function(v) { return v.k; });
    var labels   = allVars.map(function(v) { return v.l; });
    var sortedTs = Object.keys(tsMap).map(Number).sort(function(a,b) { return a-b; });

    var header = ['timestamp_ms', 'fecha', 'hora'].concat(labels);
    var rows   = [header.join(',')];

    sortedTs.forEach(function(ts) {
      var d    = new Date(ts);
      var date = d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate());
      var time = pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
      var row  = [ts, date, time];
      keys.forEach(function(k) {
        var val = tsMap[ts][k];
        row.push(val !== undefined && val !== null ? val : '');
      });
      rows.push(row.join(','));
    });
    return rows.join('\n');
  }

  /* ── FETCH AGREGADO (un solo dispositivo — sin cambios de v1) ─────── */
  function fetchAggregated(label, device, keys, startTs, endTs, interval, agg) {
    var MAX_MS = 4999 * parseInt(interval);
    var mergedData = {}, keyIdx = 0;

    function fetchNextKey() {
      if(keyIdx >= keys.length){
        showProgress(90, 'Generando CSV...');
        var csv = buildCSV(mergedData, keys);
        var filename = buildFilename(label, startTs, endTs, interval);
        downloadCSV(csv, filename);
        showProgress(100, 'Listo.');
        setLoading(false);
        var rows = countRows(mergedData);
        showResult('✅ Descargado: '+filename+' — '+rows+' registros.', 'success');
        addToHistory(label, startTs, endTs, interval, keys.length, rows);
        return;
      }
      var key = keys[keyIdx];
      showProgress(5 + Math.round((keyIdx/keys.length)*80),
        'Descargando '+key+' ('+( keyIdx+1)+'/'+keys.length+')...');

      var chunks = [], cs = startTs;
      while(cs < endTs){ var ce=Math.min(cs+MAX_MS,endTs); chunks.push({s:cs,e:ce}); cs=ce; }
      var keyData = [], chunkIdx = 0;

      function fetchNextChunk(){
        if(chunkIdx >= chunks.length){
          mergedData[key] = keyData;
          keyIdx++;
          fetchNextKey();
          return;
        }
        var chunk = chunks[chunkIdx];
        var url = '/api/plugins/telemetry/DEVICE/'+device.id+
                  '/values/timeseries?keys='+key+
                  '&startTs='+chunk.s+'&endTs='+chunk.e+
                  '&interval='+interval+'&agg='+agg+'&limit=50000';
        ctx.http.get(url).subscribe(function(data){
          if(data[key]) keyData = keyData.concat(data[key]);
          chunkIdx++;
          fetchNextChunk();
        }, function(){
          setLoading(false);
          showResult('❌ Error al obtener '+key+'. Verifica tu conexión e intenta nuevamente.', 'error');
        });
      }
      fetchNextChunk();
    }
    fetchNextKey();
  }

  /* ── FETCH RAW (B-05: paginación por variable, con tope de seguridad) ── */
  /* Antes paginaba con la suma de puntos de todas las variables y avanzaba al último ts global: si las
   * variables tenían frecuencias distintas, una cortada antes perdía el tramo sin aviso (F20). Ahora cada
   * variable pagina sola (páginas de LIMIT_PUNTOS desde su último ts) hasta completar el período o hasta
   * MAX_PAGINAS; solo si alcanza ese tope el CSV sale con lo recibido y se avisa hasta qué fecha llega. */
  function fetchRaw(label, device, vars, startTs, endTs) {
    var keys = vars.map(function (v) { return v.k; });
    var allData = {}, cortadas = [], keyIdx = 0;

    function fetchNextKey() {
      if (keyIdx >= vars.length) {
        showProgress(90, 'Generando CSV...');
        var csv      = buildCSV(allData, keys);
        var filename = buildFilename(label, startTs, endTs, 'raw');
        downloadCSV(csv, filename);
        showProgress(100, 'Listo.');
        setLoading(false);
        var rows = countRows(allData);
        showFin(filename, rows, cortadas);
        addToHistory(label, startTs, endTs, 'raw', keys.length, rows);
        return;
      }
      var v = vars[keyIdx];
      showProgress(5 + Math.round((keyIdx / vars.length) * 80),
        'Descargando ' + v.k + ' (' + (keyIdx + 1) + '/' + vars.length + ')...');
      fetchKeyRaw(device, v, startTs, endTs, cortadas, function(pts) {
        allData[v.k] = pts;
        keyIdx++;
        fetchNextKey();
      }, function() {
        setLoading(false);
        showResult('❌ Error al obtener datos. Intenta nuevamente.', 'error');
      });
    }
    fetchNextKey();
  }

  /* Raw de una variable: páginas de LIMIT_PUNTOS (orderBy=ASC), cada una desde el último ts recibido + 1.
   * Termina con una página incompleta. Si la página MAX_PAGINAS llega llena, la variable queda cortada. */
  function fetchKeyRaw(device, v, startTs, endTs, cortadas, ok, err) {
    var pts = [], desde = startTs, paginas = 0;
    function pagina() {
      var url = '/api/plugins/telemetry/DEVICE/' + device.id +
                '/values/timeseries?keys=' + v.k +
                '&startTs=' + desde + '&endTs=' + endTs +
                '&orderBy=ASC&limit=' + LIMIT_PUNTOS;
      ctx.http.get(url).subscribe(function(data) {
        var pg = (data && data[v.k]) || [], maxTs = desde;
        pg.forEach(function (p) { pts.push(p); if (p.ts > maxTs) maxTs = p.ts; });
        paginas++;
        if (pg.length < LIMIT_PUNTOS) { ok(pts); return; }
        if (paginas >= MAX_PAGINAS) { cortadas.push({ l: v.l, hasta: maxTs }); ok(pts); return; }
        desde = maxTs + 1;
        pagina();
      }, err);
    }
    pagina();
  }

  function showFin(filename, rows, cortadas) {
    if (!cortadas.length) {
      showResult('✅ Descargado: ' + filename + ' — ' + rows + ' registros.', 'success');
      return;
    }
    showResult('⚠ Descargado: ' + filename + ' — ' + rows + ' registros. Incompleto: ' +
      cortadas.map(function (c) { return c.l + ' (hasta ' + formatDateTime(c.hasta) + ')'; }).join(', ') +
      (cortadas.length > 1 ? ' llegaron' : ' llegó') + ' al tope de ' + miles(LIMIT_PUNTOS * MAX_PAGINAS) +
      ' puntos por variable. Acorta el período o usa 15 min.', 'warn');
  }

  /* ── BUILD CSV (sin cambios de v1) ──────────────────────────────── */
  function buildCSV(data, keys) {
    var tsMap = {};
    keys.forEach(function(key) {
      if (data[key]) {
        data[key].forEach(function(point) {
          if (!tsMap[point.ts]) tsMap[point.ts] = {};
          tsMap[point.ts][key] = point.value;
        });
      }
    });

    var sortedTs = Object.keys(tsMap).map(Number).sort(function(a, b) { return a - b; });
    var header   = ['timestamp_ms', 'fecha', 'hora'].concat(keys);
    var rows     = [header.join(',')];

    sortedTs.forEach(function(ts) {
      var d       = new Date(ts);
      var dateStr = d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate());
      var timeStr = pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
      var row     = [ts, dateStr, timeStr];
      keys.forEach(function(key) {
        var val = tsMap[ts][key];
        row.push(val !== undefined && val !== null ? val : '');
      });
      rows.push(row.join(','));
    });
    return rows.join('\n');
  }

  function countRows(data) {
    var tsSet = {};
    Object.keys(data).forEach(function(k) {
      if (data[k]) data[k].forEach(function(p) { tsSet[p.ts] = true; });
    });
    return Object.keys(tsSet).length;
  }

  /* ── DOWNLOAD (sin cambios de v1) ────────────────────────────────── */
  function downloadCSV(content, filename) {
    var blob = new Blob(['\uFEFF' + content], { type: 'text/csv;charset=utf-8;' });
    var url  = URL.createObjectURL(blob);
    var a    = document.createElement('a');
    a.href   = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  /* ── HISTORIAL EN MEMORIA DE SESIÓN ─────────────────────────────── */
  function addToHistory(label, startTs, endTs, gran, varCount, rows) {
    var granLabel = gran === 'raw' ? 'Raw' :
                    gran === '900000' ? '15 min' :
                    gran === '3600000' ? '1h' : '1 día';
    exportHistory.unshift({
      label:    label,
      period:   formatDate(startTs) + ' → ' + formatDate(endTs),
      gran:     granLabel,
      vars:     varCount,
      rows:     rows.toLocaleString(),
      fecha:    new Date().toLocaleDateString('es-PE', { day:'2-digit', month:'short' })
    });
    if (exportHistory.length > 3) exportHistory.splice(3);
    renderHistory();
  }

  function renderHistory() {
    var list = document.getElementById('hist-list');
    if (!list) return;
    list.innerHTML = '';
    if (exportHistory.length === 0) {
      list.innerHTML = '<div class="hist-empty">Aún no hay exportaciones en esta sesión</div>';
      return;
    }
    exportHistory.forEach(function(h) {
      var item = document.createElement('div');
      item.className = 'hist-item';
      item.innerHTML =
        '<div class="hist-info">' +
          '<div class="hist-label">' + esc(h.label) + '</div>' +
          '<div class="hist-meta">' + h.period + ' · ' + h.gran + ' · ' + h.rows + ' filas</div>' +
          '<div class="hist-fecha">' + h.fecha + '</div>' +
        '</div>' +
        '<button class="hist-btn">↺ Repetir</button>';
      list.appendChild(item);
    });
  }

  /* Inicializar historial vacío */
  renderHistory();

  /* ── HELPERS (sin cambios de v1) ─────────────────────────────────── */
  function toInputFormat(date) {
    var offset = date.getTimezoneOffset();
    var local  = new Date(date.getTime() - offset * 60000);
    return local.toISOString().slice(0, 16);
  }

  function formatDate(ts) {
    var d = new Date(ts);
    return d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate());
  }

  function buildFilename(label, startTs, endTs, gran) {
    var clean     = label.replace(/[^a-zA-Z0-9]/g, '_').replace(/_+/g, '_');
    var granLabel = gran === 'raw'     ? 'raw'   :
                    gran === '900000'  ? '15min' :
                    gran === '3600000' ? '1h'    : '1dia';
    return 'Sunkuu_' + clean + '_' + formatDate(startTs) + '_al_' + formatDate(endTs) + '_' + granLabel + '.csv';
  }

  function pad(n) { return n < 10 ? '0' + n : '' + n; }

  function formatDateTime(ts) {
    var d = new Date(ts);
    return formatDate(ts) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
  }

  function miles(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ' '); }   /* 50000 → "50 000" */

  /* Texto del registro (etiqueta, propietario) dentro de innerHTML */
  function esc(s) {
    return String(s === undefined || s === null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  function setLoading(loading) {
    var btn = document.getElementById('btn-export');
    btn.disabled = loading;
    document.getElementById('btn-text').textContent = loading ? 'Exportando...' : 'Exportar CSV';
    document.getElementById('btn-icon').textContent = loading ? '⏳' : '⬇';
    document.getElementById('exp-progress').style.display = loading ? 'flex' : 'none';
    if (!loading) document.getElementById('exp-result').style.display = 'none';
  }

  function showProgress(pct, label) {
    document.getElementById('progress-fill').style.width = pct + '%';
    document.getElementById('progress-label').textContent = label;
  }

  function showResult(msg, type) {
    var el = document.getElementById('exp-result');
    el.textContent  = msg;
    el.className    = 'exp-result ' + type;
    el.style.display = 'block';
  }
  
  /* ── RESPONSIVE JS (usa ancho del container, no del viewport) ─── */
  function applyResponsive() {
    var root  = document.getElementById('exp-root');
    var body  = document.getElementById('exp-body');
    var right = document.getElementById('exp-right');
    var sub   = document.getElementById('exp-subtitle');
    if (!root || !body) return;
    var w = root.offsetWidth || 1200;

    if (w <= 600) {
      body.style.gridTemplateColumns  = '1fr';
      if (right) right.style.order   = '-1';
      if (sub)   sub.style.display   = 'none';
    } else if (w <= 900) {
      body.style.gridTemplateColumns  = '1fr';
      if (right) right.style.order   = '';
      if (sub)   sub.style.display   = '';
    } else {
      body.style.gridTemplateColumns  = '3fr 2fr';
      if (right) right.style.order   = '';
      if (sub)   sub.style.display   = '';
    }
  }
  applyResponsive();
  window.addEventListener('resize', applyResponsive);
};

